// managedUsersListURL builds the initial hx-get URL for the users list
// partial, preserving whatever filters are already active in the query
// string (e.g. a deep link or a full-page reload with filters applied).
func managedUsersListURL(filter ManagedUserFilter) templ.SafeURL {
	q := url.Values{}
	if filter.Q != "" {
		q.Set("q", filter.Q)
	}
	if filter.Role != "" {
		q.Set("role", filter.Role)
	}
	if filter.Status != "" {
		q.Set("status", filter.Status)
	}
	if filter.Project != "" {
		q.Set("project", filter.Project)
	}
	if len(q) == 0 {
		return templ.SafeURL("/dashboard/admin/users/list")
	}
	return templ.SafeURL("/dashboard/admin/users/list?" + q.Encode())
}

